<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import StockReturnDiscoveryPanel from '../components/StockReturnDiscoveryPanel.vue'
import {discoveryPending} from '../stockReturnDiscovery'
import { RouterLink,useRouter } from 'vue-router'
import { api,ApiError,date,type Staff,type Page } from '../api'
import {enrollReturnJob,readReturnJob,lastReturnJob,type ReturnJobAudit} from '../stockReturnRecovery'
import { pending,busy,commandMessage } from '../commands'
import { stockPending,rebuild,retryMaintenance,lastMaintenance,maintenanceMessage,type StockTicket,type StockIssue,type MaintenanceAudit } from '../stockMaintenance'
import {reviewPending,review,retryReview,lastReview,reviewMessage,type ReviewAudit} from '../stockReviews'
import {returnPending,startReturn,retryReturn,readReturn,lastReturn,returnMessage,returnReason,type ReturnCandidate,type ReturnAudit} from '../stockReturns'
import {resolutionPending,reconcileResolution,startResolution,retryResolution,readResolution,lastResolution,resolutionMessage,resolutionReason,type ResolutionPreview,type ResolutionAudit,type RecoveryAudit} from '../stockReturnResolutions'
const resolutionPreview=ref<ResolutionPreview|null>(null),resolutionHistory=ref<Page<ResolutionAudit>|null>(null)
const returnRecoveryEnabled=ref(false),returnJobHistory=ref<Page<ReturnJobAudit>|null>(null)
const ownReturnJob=computed(()=>{const v=lastReturnJob.value;return v&&v.owner===staff.value?.username&&(v.job.requestId===ownReturn.value?.requestId||v.job.requestId===pending.value?.body.requestId)?v.job:null})
const recoveryHistory=ref<Page<RecoveryAudit>|null>(null)
const ownResolution=computed(()=>{const v=lastResolution.value;return v&&v.owner===staff.value?.username?v.receipt:null})
const returnEnabled=ref(false),returnPage=ref(1),returns=ref<Page<ReturnCandidate>|null>(null),returnHistory=ref<Page<ReturnAudit>|null>(null)
const ownReturn=computed(()=>{const value=lastReturn.value;return value&&value.owner===staff.value?.username?value.receipt:null})
const reviewEnabled=ref(false),reviewHistory=ref<Page<ReviewAudit>|null>(null)
const ownReview=computed(()=>{const value=lastReview.value;return value&&value.owner===staff.value?.username&&(!pending.value||pending.value.body.requestId===value.receipt.requestId)?value.receipt:null})
const router=useRouter(),staff=ref<Staff|null>(null),list=ref<Page<StockTicket>|null>(null),selected=ref<StockTicket|null>(null),issues=ref<Page<StockIssue>|null>(null),history=ref<Page<MaintenanceAudit>|null>(null),page=ref(1),issuePage=ref(1),error=ref(''),loading=ref(false)
const ownReceipt=computed(()=>{const value=lastMaintenance.value;return value&&value.owner===staff.value?.username?value.receipt:null})
const editable=computed(()=>staff.value?.canWrite&&selected.value?.maintenanceEnabled&&!selected.value.unresolvedIntents&&!pending.value&&!busy.value&&!loading.value)
const state=(s:string)=>({READY:'可供預扣',DIRTY:'待維護核對',CLOSED:'重建中',REGISTERED:'已登記',BLOCKED:'已確認受阻',REVIEW:'待人工核對',HELD:'暫時預扣',ABORTING:'放棄核對中',PREPARED:'意圖已保存'}[s]||s)
async function load(){error.value='';loading.value=true;try{const [tickets,settings,returnSettings,recoverySettings]=await Promise.all([api<Page<StockTicket>>(`/admin/stock/tickets?page=${page.value}&size=12`),api<{enabled:boolean}>('/admin/stock/review-settings'),api<{enabled:boolean}>('/admin/stock/return-settings'),api<{enabled:boolean}>('/admin/stock/return-recovery-settings')]);list.value=tickets;reviewEnabled.value=settings.enabled;returnEnabled.value=returnSettings.enabled;returnRecoveryEnabled.value=recoverySettings.enabled;if(selected.value)await select(selected.value.ticketId,false)}catch(e){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===401)await router.push('/staff/login')}finally{loading.value=false}}
async function select(id:string,reset=true){if(reset){issuePage.value=1;returnPage.value=1;}error.value='';try{const [t,p,candidates]=await Promise.all([api<StockTicket>('/admin/stock/tickets/'+id),api<Page<StockIssue>>(`/admin/stock/tickets/${id}/issues?page=${issuePage.value}&size=12`),api<Page<ReturnCandidate>>(`/admin/stock/tickets/${id}/return-candidates?page=${returnPage.value}&size=12`)]);selected.value=t;issues.value=p;returns.value=candidates}catch(e){error.value=(e as Error).message}}
async function audit(){if(!ownReceipt.value)return;history.value=await api('/admin/stock/rebuilds/'+ownReceipt.value.requestId+'/audit')}
async function start(){if(!staff.value||!selected.value||!editable.value)return;error.value='';try{await rebuild(staff.value,selected.value);await audit();await load()}catch(e){error.value=(e as Error).message}}
async function retry(){if(!staff.value)return;error.value='';try{if(resolutionPending()){await retryResolution(staff.value);await auditResolution()}else if(returnPending()){await retryReturn(staff.value);await auditReturn()}else if(reviewPending()){await retryReview(staff.value);await auditReview()}else{await retryMaintenance(staff.value);await audit()}await load()}catch(e){error.value=(e as Error).message}}
async function auditReview(){if(ownReview.value)reviewHistory.value=await api('/admin/stock/reviews/'+ownReview.value.requestId+'/audit')}
async function resolve(i:StockIssue,kind:'UNUSED'|'SETTLEMENT'){if(!staff.value||!staff.value.canWrite||!reviewEnabled.value||pending.value||busy.value||loading.value)return;error.value='';try{await review(staff.value,i,kind);await auditReview();await load()}catch(e){error.value=(e as Error).message}}
async function readJob(){if(!staff.value)return;const id=ownReturn.value?.requestId||String(pending.value?.body.requestId||'');const rev=ownReturn.value?.expectedReleaseRevision||Number(pending.value?.body.expectedReleaseRevision);if(id&&rev>0){await readReturnJob(staff.value,id,rev);returnJobHistory.value=await api(`/admin/stock/returns/${id}/recovery-job/audit`)}}
async function queueReturn(){if(!staff.value)return;error.value='';try{await enrollReturnJob(staff.value);await readJob()}catch(e){error.value=(e as Error).message}}
async function auditReturn(){if(ownReturn.value&&staff.value){returnHistory.value=await api('/admin/stock/returns/'+ownReturn.value.requestId+'/audit');resolutionPreview.value=await readResolution(staff.value,ownReturn.value.requestId);await auditResolution();await readJob();recoveryHistory.value=await api(`/admin/stock/returns/${ownReturn.value.requestId}/resolution/recovery-audit`)}}
async function auditResolution(){if(ownResolution.value)resolutionHistory.value=await api('/admin/stock/returns/'+ownResolution.value.requestId+'/resolution/audit')}
async function stopResolution(){if(!staff.value)return;error.value='';try{await reconcileResolution(staff.value);await auditReturn();await load()}catch(e){error.value=(e as Error).message}}
async function closeReturn(){if(!staff.value||!resolutionPreview.value||resolutionPreview.value.requestId!==ownReturn.value?.requestId)return;error.value='';try{await startResolution(staff.value,resolutionPreview.value);await auditReturn();await load()}catch(e){error.value=(e as Error).message}}
async function handoff(c:ReturnCandidate){if(!staff.value||!staff.value.canWrite||!returnEnabled.value||!c.canBegin||pending.value||busy.value||loading.value)return;error.value='';try{await startReturn(staff.value,c);await auditReturn();await load()}catch(e){error.value=(e as Error).message}}
async function originalReturn(c:ReturnCandidate){if(!staff.value)return;error.value='';try{await readReturn(staff.value,c);await auditReturn()}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{try{staff.value=await api('/auth/me');await load()}catch{await router.push('/staff/login')}})
</script>
<template><section v-if="staff" class="content admin-page stock-page"><RouterLink to="/staff" class="back-link">← 活動管理</RouterLink><div class="section-heading"><div><div class="eyebrow">STOCK MAINTENANCE</div><h1>庫存維護與核對</h1><p>{{staff.username}} · {{staff.canWrite?'管理員':'唯讀員工'}}</p></div><button :disabled="loading||busy" @click="load">重讀目前狀態</button></div><p class="notice">正式票額由訂單資料決定。暫時預扣與待核對工作解決後，才可重建投影；此清單顯示已保存的狀態。</p>
 <div v-if="pending" class="notice warning" role="status"><strong>有一筆員工操作尚未確認，其他寫入暫停。</strong><p>原員工：{{pending.owner}}</p><template v-if="stockPending()||reviewPending()||returnPending()||resolutionPending()"><code>{{pending.body.requestId}}</code><p v-if="pending.owner!==staff.username">目前帳號不能接管，請由原員工登入核對。</p><button :disabled="busy||pending.owner!==staff.username" @click="retry">核對原維護操作</button><div v-if="returnPending()&&staff.canWrite&&pending.owner===staff.username"><p>背景工作只續做原返還內容，六次預算耗盡即轉人工核對；確認完成前仍暫停其他寫入。</p><button :disabled="busy||!returnRecoveryEnabled" @click="queueReturn">將原返還交給背景恢復</button></div><div v-if="resolutionPending()&&staff.canWrite&&pending.owner===staff.username"><p>若原內容無法繼續，可核對是否已結案；未結案時會永久停止這份內容，之後只能明確換綁另一份快照。</p><button :disabled="busy" @click="stopResolution">核對並永久停止原結案內容</button></div></template><a v-else-if="discoveryPending()" href="#return-discovery">核對原自動返還操作 ↓</a><RouterLink v-else to="/staff">回活動管理核對原操作 ↗</RouterLink></div>
 <p v-if="commandMessage" class="notice" role="status">{{commandMessage}}</p><p v-if="ownReceipt" class="notice" role="status">{{maintenanceMessage(ownReceipt)}} 原操作：{{ownReceipt.requestId}} · {{state(ownReceipt.state)}} · 目前{{state(ownReceipt.currentState)}}</p><p v-if="ownReview" class="notice" role="status">{{reviewMessage(ownReview)}} 原人工操作：{{ownReview.requestId}} · {{ownReview.state}} · {{ownReview.resolution||ownReview.failure||'待核對'}}</p><p v-if="ownReturn" class="notice" role="status">{{returnMessage(ownReturn)}} 原返還操作：{{ownReturn.requestId}} · {{ownReturn.state}} · {{ownReturn.failure||'已保存'}}</p><p v-if="ownResolution" class="notice" role="status">{{resolutionMessage}} 原返還：{{ownResolution.requestId}} · ABSORBED</p><div v-if="error" class="notice error" role="alert">{{error}}</div>
 <section v-if="ownReturnJob" class="panel"><h2>原返還背景恢復</h2><p>{{ownReturnJob.state}} · 已用 {{ownReturnJob.attempts}}／{{ownReturnJob.maxAttempts}} 次 · {{ownReturnJob.lastCode||'待領取'}}</p><p>原返還 <code>{{ownReturnJob.requestId}}</code></p><p v-if="ownReturnJob.state==='REVIEW'">預算或來源／權限核對已停止，需由原管理員核對；不重新開啟工作預算。</p><button :disabled="busy" @click="readJob">重讀原背景工作</button><p v-for="a in returnJobHistory?.items" :key="a.version">第 {{a.version}} 筆 · {{a.state}} · {{a.attempts}} 次 · {{a.lastCode||'已保存'}}</p></section><div class="admin-grid"><aside class="panel event-sidebar"><h2>票種投影</h2><button v-for="t in list?.items" :key="t.ticketId" class="event-select" :data-ticket-id="t.ticketId" :class="{selected:selected?.ticketId===t.ticketId}" @click="select(t.ticketId)"><strong>{{t.eventTitle}} · {{t.ticketName}}</strong><span>{{state(t.state)}} · 未解決 {{t.unresolvedIntents}} · REVIEW {{t.unresolvedReviews}}</span></button><p v-if="!list?.items.length">尚無票種。</p><div class="pagination"><button :disabled="page===1||loading" @click="page--;load()">上一頁</button><span>{{page}}</span><button :disabled="!list||page*12>=list.total||loading" @click="page++;load()">下一頁</button></div></aside>
 <div><StockReturnDiscoveryPanel :staff="staff" :ticket-id="selected?.ticketId||''" :disabled="loading"/><section v-if="selected" class="panel"><h2>{{selected.eventTitle}} · {{selected.ticketName}}</h2><p>{{selected.sessionName}} · 正式可售 {{selected.available}} 張</p><p>投影：{{state(selected.state)}} · 票額修訂 {{selected.sourceRevision}} · 世代 {{selected.generation}}</p><p v-if="!staff.canWrite" class="notice">唯讀員工可核對狀態，維護操作需要管理權限。</p><p v-else-if="!selected.maintenanceEnabled" class="notice">維護寫入目前關閉，仍可核對紀錄。</p><p v-if="selected.unresolvedIntents" class="notice warning">尚有 {{selected.unresolvedIntents}} 筆預扣未解決，重建暫停。REVIEW 工作 {{selected.unresolvedReviews}} 筆，請先核對原決定。</p><button v-if="staff.canWrite" class="primary" :disabled="!editable" @click="start">依目前票額開始重建</button></section>
 <section v-if="selected" class="panel"><h2>未解決預扣與人工核對</h2><p class="muted">依原決定核對，不修改 REVIEW 歷史與嘗試次數。來源衝突與損壞台帳仍會阻擋。</p><p v-if="staff.canWrite&&!reviewEnabled" class="notice">人工核對寫入目前關閉，仍可查看問題與原紀錄。</p><p v-if="!issues?.total">此票種目前沒有未解決的預扣。</p><article v-for="i in issues?.items" :key="i.intentId" class="stock-issue" :data-intent-id="i.intentId"><strong>{{state(i.state)}} · {{i.purchaseStatus||'尚未正式受理'}}</strong><p>原購票操作 <code>{{i.requestId}}</code></p><p>原預扣期限 {{date(i.deadlineAt)}} · 正式決定 {{i.decision||'尚未產生'}} · 核對結果 {{i.acknowledgement||'尚未確認'}}</p><p>未使用工作 {{i.unusedJob||'無'}}／嘗試 {{i.unusedAttempts??0}} · 正式決定工作 {{i.settlementJob||'無'}}／嘗試 {{i.settlementAttempts??0}}</p><p v-if="i.unusedCode||i.settlementCode">核對訊號 {{i.unusedCode||i.settlementCode}}</p><button v-if="staff.canWrite&&i.unusedJob==='REVIEW'&&i.state==='ABORTING'&&!i.purchaseStatus&&!i.decision" :disabled="!reviewEnabled||!!pending||busy||loading" @click="resolve(i,'UNUSED')">核對未使用預扣</button><button v-if="staff.canWrite&&i.settlementJob==='REVIEW'&&['COMMIT','RELEASE'].includes(i.decision||'')" :disabled="!reviewEnabled||!!pending||busy||loading" @click="resolve(i,'SETTLEMENT')">核對正式決定</button><details><summary>核對識別碼</summary><code>{{i.intentId}}</code></details></article><div v-if="issues&&issues.total>12" class="pagination"><button :disabled="issuePage===1" @click="issuePage--;select(selected.ticketId,false)">前一頁問題</button><span>{{issuePage}}</span><button :disabled="issuePage*12>=issues.total" @click="issuePage++;select(selected.ticketId,false)">下一頁問題</button></div></section>
 <section v-if="selected" class="panel"><h2>取消／到期返還接棒</h2><p class="muted">依原正式返還證據建立新世代，保留原預扣收據。完成紀錄不代表目前投影仍可預扣。</p><p v-if="!returnEnabled" class="notice">返還寫入目前關閉，仍可查看原證據與紀錄。</p><p v-if="!returns?.total">此票種尚無已核對 COMMIT 的正式取消／到期來源。</p><article v-for="c in returns?.items" :key="c.orderId" class="stock-issue" :data-return-order="c.orderId"><strong>{{c.orderStatus==='EXPIRED'?'已到期':'已取消'}} · {{c.quantity}} 張</strong><p>原訂單 <code>{{c.orderId}}</code> · 返還修訂 {{c.releaseRevision}}</p><p>{{returnReason(c)}}<span v-if="c.operationState"> · 原操作 {{c.operationState}}</span></p><button v-if="staff.canWrite&&!c.operationState" :disabled="!c.canBegin||!!pending||busy||loading" @click="handoff(c)">依原返還證據接棒</button><button v-if="c.ownRequestId" :disabled="!!pending||busy||loading" @click="originalReturn(c)">讀取原返還操作</button></article><div v-if="returns&&returns.total>12" class="pagination"><button :disabled="returnPage===1" @click="returnPage--;select(selected.ticketId,false)">前一頁返還</button><span>{{returnPage}}</span><button :disabled="returnPage*12>=returns.total" @click="returnPage++;select(selected.ticketId,false)">下一頁返還</button></div></section>
 <section v-if="resolutionPreview&&ownReturn?.state==='BLOCKED'&&resolutionPreview.requestId===ownReturn.requestId" class="panel"><h2>返還結案證據</h2><p>{{resolutionReason(resolutionPreview)}}</p><p v-if="resolutionPreview.replacement">已發布替換快照 <code>{{resolutionPreview.replacement.replacementRequestId}}</code> · 修訂 {{resolutionPreview.replacement.snapshotRevision}} · 世代 {{resolutionPreview.replacement.generation}} · 基準 {{resolutionPreview.replacement.available}} 張</p><p>結案只保存原返還與快照的關聯，不再補票，不改原受阻紀錄。</p><button v-if="staff.canWrite&&!resolutionPreview.resolution" :disabled="!resolutionPreview.canResolve||!!pending||busy||loading" @click="closeReturn">{{resolutionPreview.fence?'明確換綁新快照並結案':'依已發布快照結案'}}</button></section><section v-if="recoveryHistory?.total" class="panel"><h2>結案核對與換綁紀錄</h2><p v-for="a in recoveryHistory.items" :key="a.replacementRequestId+a.action">{{a.action==='NOT_APPLIED'?'原內容永久停止':'明確換綁'}} · {{date(a.createdAt)}} · <code>{{a.replacementRequestId}}</code><span v-if="a.previousReplacementRequestId"> · 原快照 <code>{{a.previousReplacementRequestId}}</code></span></p></section><section v-if="resolutionHistory" class="panel"><h2>原返還結案紀錄</h2><p v-for="a in resolutionHistory.items" :key="a.requestId">{{a.state}} · {{date(a.createdAt)}} · 已發布世代 {{a.generation}}</p></section><section v-if="returnHistory" class="panel"><h2>原返還操作紀錄</h2><p v-for="a in returnHistory.items" :key="a.version">第 {{a.version}} 次紀錄 · {{a.state}} · {{date(a.createdAt)}} · {{a.failure||'已保存'}}</p></section><section v-if="reviewHistory" class="panel"><h2>原人工核對紀錄</h2><p v-for="a in reviewHistory.items" :key="a.version">第 {{a.version}} 次紀錄 · {{a.state}} · {{date(a.createdAt)}} · {{a.resolution||a.failure||'待核對'}}</p></section><section v-if="history" class="panel"><h2>原維護操作紀錄</h2><p v-for="a in history.items" :key="a.version">第 {{a.version}} 次紀錄 · {{state(a.state)}} · {{date(a.createdAt)}} <span v-if="a.failure">· {{a.failure}}</span></p></section></div></div></section></template>
<style scoped>.stock-page code,.stock-issue{overflow-wrap:anywhere}.stock-issue{padding:1rem 0;border-top:1px solid var(--line,#ddd)}</style>
